create or replace function private.sites_configuration_is_valid_v1(p_sites jsonb) returns boolean
language sql immutable security invoker set search_path='' as $$
 select case when p_sites?'onzeTrotsStyle' then coalesce(
  p_sites->>'provider'='menu' and p_sites->'menuWidgets'='true'::jsonb
  and jsonb_typeof(p_sites->'onzeTrotsStyle')='string'
  and p_sites->>'onzeTrotsStyle' in('v9-marker-light','v9-marker-dark','v10-barlow-light','v10-barlow-dark')
  and private.sites_configuration_before_approved_menu_v1(p_sites-'onzeTrotsStyle'),false)
 else private.sites_configuration_before_approved_menu_v1(p_sites) end
$$;

-- A synthetic pool-context hash is not a Sportlink poulecode. Recover it only
-- through an exact, unique own-team + competition/phase/season catalog match,
-- including verification of the mapper's original SHA-256 identity. Never fuzzy names.
create function private.sync_sportlink_effective_pool_v1(p_match public.sports_matches)
returns text language plpgsql stable security definer set search_path='' as $$
declare pool_id text:=coalesce(p_match.pool->>'externalId',p_match.pool->>'poolExternalId');resolved text;matches integer;
begin
 if pool_id is null or pool_id!~'^[a-f0-9]{64}$' then return pool_id;end if;
 select count(distinct option->>'poolExternalId'),min(option->>'poolExternalId') into matches,resolved
 from public.sports_teams team cross join lateral jsonb_array_elements(coalesce(team.metadata->'competitionOptions','[]'::jsonb))option
 where team.tenant_id=p_match.tenant_id and team.source_connection_id=p_match.source_connection_id and team.active
  and team.external_id in(p_match.home_team->>'externalId',p_match.away_team->>'externalId')
  and option->>'externalId'=private.sportlink_competition_identity_v1(p_match.competition,p_match.pool)
  and nullif(option->>'period','') is not distinct from nullif(p_match.competition->>'period','')
  and nullif(option->>'season','unknown') is not distinct from nullif(p_match.competition->>'season','unknown')
  and nullif(option->>'poolExternalId','') is not null
  and pool_id=encode(extensions.digest(convert_to('pool-context','UTF8')||decode('00','hex')||convert_to((option->>'externalId')||'|'||(option->>'poolName'),'UTF8'),'sha256'),'hex');
 return case when matches=1 then resolved end;
end;$$;

