alter function private.build_dynamic_snapshot_data(public.dynamic_slides) rename to build_dynamic_snapshot_before_s291_v1;
create function private.build_dynamic_snapshot_data(p_slide public.dynamic_slides)returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;logo text;
begin
 if p_slide.configuration_json#>>'{syncConfiguration,seed,authoring,visualRevision}'='onzetrots-20261024' and p_slide.slide_type like 'sport\_%'escape'\' then
  result:=private.build_sync_sport_snapshot_s291_v1(p_slide);
 else result:=private.build_dynamic_snapshot_before_s291_v1(p_slide);end if;
 if p_slide.slide_type='news' then
  select config_json->>'providerLogoOverrideMediaAssetId' into logo from public.dynamic_data_sources where tenant_id=p_slide.tenant_id and id=p_slide.data_source_id and kind='rss';
  if logo is not null then result:=jsonb_set(result,'{news,providerLogoMediaAssetId}',to_jsonb(logo));end if;
 end if;
 return result;
end;$$;

-- A per-feed, explicit own-media override; opening/checking a slide never calls this.
create function public.set_rss_provider_logo_v1(p_tenant_id uuid,p_source_id uuid,p_media_asset_id uuid)
returns void language plpgsql security definer set search_path='' as $$
begin
 if private.current_user_id() is null or not private.has_tenant_capability(p_tenant_id,'tenant.data_source.manage')
  or not exists(select 1 from public.tenants where id=p_tenant_id and status='active')
 then raise exception 'RSS logo permission denied'using errcode='42501';end if;
 if not exists(select 1 from public.dynamic_data_sources where id=p_source_id and tenant_id=p_tenant_id and kind='rss' and status<>'archived')
 then raise exception 'RSS source unavailable'using errcode='42501';end if;
 if p_media_asset_id is not null and not exists(select 1 from public.media_assets where id=p_media_asset_id and tenant_id=p_tenant_id and kind='image' and status='ready' and deleted_at is null)
 then raise exception 'RSS logo unavailable in this tenant'using errcode='23514';end if;
 update public.dynamic_data_sources set revision=revision+1,config_json=case when p_media_asset_id is null then config_json-'providerLogoOverrideMediaAssetId' else config_json||jsonb_build_object('providerLogoOverrideMediaAssetId',p_media_asset_id)end
 where id=p_source_id and tenant_id=p_tenant_id and config_json->>'providerLogoOverrideMediaAssetId' is distinct from p_media_asset_id::text;
 perform private.audit_event(p_tenant_id,'dynamic.rss.provider_logo_changed','dynamic_data_sources',p_source_id,'success',jsonb_build_object('mediaAssetId',p_media_asset_id));
end;$$;

